<template>
  <div class="moves_nav">
    <p>moves</p>
    <div class="filter">
      <div class="filter_type">
        <select v-model="type" name="" id="">
          <option selected value="all">all</option>
          <option value="income">income</option>
          <option value="expense">exprense</option>
        </select>
      </div>
    </div>
  </div>
  <h3
    style="text-align: center; font-size: 23px; padding: 10px; color: #999999"
    v-if="allMovements.length == 0"
  >
    No momvements yet, add some
  </h3>
  <ul v-else>
    <move-element
      v-for="movement in allMovements"
      :movementItem="movement"
      :key="movement.title"
    ></move-element>
  </ul>
</template>
<script>
import MoveElement from "../components/MoveElement.vue";
export default {
  data() {
    return {
      type: "all",
    };
  },
  components: {
    MoveElement,
  },
  computed: {
    allMovements() {
      if (this.type == "all") {
        return this.$store.getters.getMoves;
      } else if (this.type == "income") {
        return this.$store.getters.getIncomes;
      } else {
        return this.$store.getters.getExpenses;
      }
    },
  },
  created() {
    console.log("I done");
    this.$store.dispatch("setMovements");
  },
};
</script>
<style scoped>
.moves_nav p {
  color: white;
}
.moves_nav {
  align-items: center;
  justify-content: space-between;
  border-radius: 6px;
  background-color: #1a1f14;
  padding: 10px;
  display: flex;
}
.filter {
  gap: 8px;
  display: flex;
}
option {
  font-size: 12px;
  color: black;
}
select {
  outline: none;
  color: white;
  font-size: 16px;
  background: none;
  border: none;
}

.search {
  height: 20px;
  width: 20px;
}
.search img {
  cursor: pointer;
  height: 100%;
  width: 100%;
  filter: brightness(0) saturate(100%) invert(95%) sepia(22%) saturate(233%)
    hue-rotate(24deg) brightness(92%) contrast(83%);
}
@media (min-width: 850px) {
  ul {
  scrollbar-width: thin;
  height: 507px;
  scrollbar-color: #292121 #333c2b;
  overflow-y: auto;
}
}
</style>
